"use client";

import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import api from "@/lib/axios";
import { Loader2, Save, Shield } from "lucide-react";
import { toast } from "sonner";

interface VendorProfile {
    id: string;
    firstName: string;
    surname: string;
    email: string;
    phone: string;
    profilePhoto: string;
    fullAddress: string;
    licenseNumber: string;
    panCard: string;
    pincode: string;
    state: string;
    knownLanguages: string[];
    documents: { type: string; url: string; uploadedAt: string }[];
    bankDetails: {
        accountHolderName: string;
        accountNumber: string;
        bankName: string;
        ifscCode: string;
        mmicCode: string;
    };
    status: string;
    rejectionReason: string;
}

export default function ProfilePage() {
    const [profile, setProfile] = useState<VendorProfile | null>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [form, setForm] = useState({
        firstName: "", surname: "", email: "", fullAddress: "",
        licenseNumber: "", panCard: "", pincode: "", state: "",
        knownLanguages: "",
    });
    const [bank, setBank] = useState({
        accountHolderName: "", accountNumber: "", bankName: "", ifscCode: "", mmicCode: "",
    });
    const [docType, setDocType] = useState("license");
    const [docUrl, setDocUrl] = useState("");
    const [uploadingDoc, setUploadingDoc] = useState(false);

    useEffect(() => {
        const fetchProfile = async () => {
            try {
                const res = await api.get("/vendor-auth/profile");
                const v = res.data.vendor;
                setProfile(v);
                setForm({
                    firstName: v.firstName || "",
                    surname: v.surname || "",
                    email: v.email || "",
                    fullAddress: v.fullAddress || "",
                    licenseNumber: v.licenseNumber || "",
                    panCard: v.panCard || "",
                    pincode: v.pincode || "",
                    state: v.state || "",
                    knownLanguages: v.knownLanguages?.join(", ") || "",
                });
                setBank({
                    accountHolderName: v.bankDetails?.accountHolderName || "",
                    accountNumber: v.bankDetails?.accountNumber || "",
                    bankName: v.bankDetails?.bankName || "",
                    ifscCode: v.bankDetails?.ifscCode || "",
                    mmicCode: v.bankDetails?.mmicCode || "",
                });
            } catch {
                toast.error("Failed to load profile");
            } finally {
                setLoading(false);
            }
        };
        fetchProfile();
    }, []);

    const handleSave = async () => {
        try {
            setSaving(true);
            await api.put("/vendor-auth/profile", {
                ...form,
                knownLanguages: form.knownLanguages.split(",").map(l => l.trim()).filter(Boolean),
                bankDetails: bank,
            });
            toast.success("Profile updated");
        } catch {
            toast.error("Failed to update profile");
        } finally {
            setSaving(false);
        }
    };

    const handleUploadDoc = async () => {
        if (!docUrl.trim()) { toast.error("Document URL is required"); return; }
        try {
            setUploadingDoc(true);
            const res = await api.post("/vendor-auth/upload-document", { type: docType, url: docUrl });
            setProfile(prev => prev ? { ...prev, documents: res.data.documents } : prev);
            setDocUrl("");
            toast.success("Document uploaded");
        } catch {
            toast.error("Failed to upload document");
        } finally {
            setUploadingDoc(false);
        }
    };

    const getStatusBadge = (status: string) => {
        const colors: Record<string, string> = {
            approved: "bg-green-100 text-green-800",
            pending: "bg-yellow-100 text-yellow-800",
            rejected: "bg-red-100 text-red-800",
            suspended: "bg-gray-100 text-gray-800",
        };
        return colors[status] || "bg-gray-100 text-gray-800";
    };

    if (loading) return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin text-[#8D0303]" /></div>;

    return (
        <div className="space-y-6 pb-8">
            <div className="sticky top-0 z-20 bg-background/95 backdrop-blur border-b border-border -mx-6 px-6 py-4 mb-6">
                <div className="flex items-center justify-between">
                    <div>
                        <div className="flex items-center gap-2 text-xs text-muted-foreground mb-0.5">
                            <span>Dashboard</span><span>/</span>
                            <span className="text-[#8D0303] font-medium">Profile</span>
                        </div>
                        <h1 className="text-xl font-bold">My Profile</h1>
                    </div>
                    <span className={`text-xs font-bold px-3 py-1 rounded-full capitalize ${getStatusBadge(profile?.status || "")}`}>
                        <Shield className="w-3 h-3 inline mr-1" />{profile?.status}
                    </span>
                </div>
            </div>

            {/* Personal Info */}
            <Card className="border shadow-sm">
                <CardContent className="p-6 space-y-4">
                    <h2 className="font-bold text-lg">Personal Information</h2>
                    <div className="grid grid-cols-2 gap-4">
                        <div><Label>First Name</Label><Input value={form.firstName} onChange={(e) => setForm({ ...form, firstName: e.target.value })} className="mt-1" /></div>
                        <div><Label>Surname</Label><Input value={form.surname} onChange={(e) => setForm({ ...form, surname: e.target.value })} className="mt-1" /></div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div><Label>Email</Label><Input value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} className="mt-1" /></div>
                        <div><Label>Phone</Label><Input value={profile?.phone || ""} disabled className="mt-1 bg-muted" /></div>
                    </div>
                    <div><Label>Full Address</Label><Input value={form.fullAddress} onChange={(e) => setForm({ ...form, fullAddress: e.target.value })} className="mt-1" /></div>
                    <div className="grid grid-cols-2 gap-4">
                        <div><Label>Pincode</Label><Input value={form.pincode} onChange={(e) => setForm({ ...form, pincode: e.target.value })} className="mt-1" /></div>
                        <div><Label>State</Label><Input value={form.state} onChange={(e) => setForm({ ...form, state: e.target.value })} className="mt-1" /></div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div><Label>License Number</Label><Input value={form.licenseNumber} onChange={(e) => setForm({ ...form, licenseNumber: e.target.value })} className="mt-1" /></div>
                        <div><Label>PAN Card</Label><Input value={form.panCard} onChange={(e) => setForm({ ...form, panCard: e.target.value })} className="mt-1" /></div>
                    </div>
                    <div><Label>Known Languages (comma separated)</Label><Input value={form.knownLanguages} onChange={(e) => setForm({ ...form, knownLanguages: e.target.value })} placeholder="Telugu, Hindi, English" className="mt-1" /></div>
                </CardContent>
            </Card>

            {/* Bank Details */}
            <Card className="border shadow-sm">
                <CardContent className="p-6 space-y-4">
                    <h2 className="font-bold text-lg">Bank Details</h2>
                    <div><Label>Account Holder Name</Label><Input value={bank.accountHolderName} onChange={(e) => setBank({ ...bank, accountHolderName: e.target.value })} className="mt-1" /></div>
                    <div className="grid grid-cols-2 gap-4">
                        <div><Label>Account Number</Label><Input value={bank.accountNumber} onChange={(e) => setBank({ ...bank, accountNumber: e.target.value })} className="mt-1" /></div>
                        <div><Label>Bank Name</Label><Input value={bank.bankName} onChange={(e) => setBank({ ...bank, bankName: e.target.value })} className="mt-1" /></div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div><Label>IFSC Code</Label><Input value={bank.ifscCode} onChange={(e) => setBank({ ...bank, ifscCode: e.target.value })} className="mt-1" /></div>
                        <div><Label>MMIC Code</Label><Input value={bank.mmicCode} onChange={(e) => setBank({ ...bank, mmicCode: e.target.value })} className="mt-1" /></div>
                    </div>
                </CardContent>
            </Card>

            {/* Documents */}
            <Card className="border shadow-sm">
                <CardContent className="p-6 space-y-4">
                    <h2 className="font-bold text-lg">Documents</h2>
                    {profile?.documents && profile.documents.length > 0 && (
                        <div className="space-y-2">
                            {profile.documents.map((doc, i) => (
                                <div key={i} className="flex items-center justify-between bg-muted/30 rounded-lg p-3">
                                    <div>
                                        <span className="text-xs font-bold capitalize bg-[#8D0303]/10 text-[#8D0303] px-2 py-0.5 rounded">{doc.type.replace("_", " ")}</span>
                                        <p className="text-xs text-muted-foreground mt-1 truncate max-w-xs">{doc.url}</p>
                                    </div>
                                    <span className="text-xs text-muted-foreground">{new Date(doc.uploadedAt).toLocaleDateString()}</span>
                                </div>
                            ))}
                        </div>
                    )}
                    <div className="flex items-end gap-3">
                        <div className="flex-1">
                            <Label>Document Type</Label>
                            <select value={docType} onChange={(e) => setDocType(e.target.value)} className="mt-1 w-full h-10 rounded-md border border-input bg-background px-3 text-sm">
                                <option value="license">License</option>
                                <option value="address_proof">Address Proof</option>
                                <option value="id_proof">ID Proof</option>
                            </select>
                        </div>
                        <div className="flex-[2]">
                            <Label>Document URL</Label>
                            <Input value={docUrl} onChange={(e) => setDocUrl(e.target.value)} placeholder="https://..." className="mt-1" />
                        </div>
                        <Button onClick={handleUploadDoc} disabled={uploadingDoc} className="bg-[#8D0303] hover:bg-[#700202] text-white shrink-0">
                            {uploadingDoc ? <Loader2 className="w-4 h-4 animate-spin" /> : "Upload"}
                        </Button>
                    </div>
                </CardContent>
            </Card>

            <Button onClick={handleSave} disabled={saving} className="bg-[#8D0303] hover:bg-[#700202] text-white">
                {saving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
                Save Profile
            </Button>
        </div>
    );
}
